import { isLocationHint } from "./location";
import { directoryNameForUser } from "./operations";

// The one place that builds Durable Object stubs, so the rule "the Directory is
// never on the data path" can be checked in a single file.

/** The control plane. Called only by sign-in, account deletion and admin routes. */
export function directory(env: Env) {
  return directoryByName(env, "global");
}

/** Names are generated by routing code, never accepted from an HTTP parameter. */
export function directoryByName(env: Env, name: string) {
  if (name !== "global" && !/^directory-(?:[0-9]|1[0-5])$/.test(name))
    throw new Error("invalid_directory_name");
  const id = env.DIRECTORY.idFromName(name);
  const hint = env.DIRECTORY_HINT;
  return isLocationHint(hint)
    ? env.DIRECTORY.get(id, { locationHint: hint })
    : env.DIRECTORY.get(id);
}

/** Cookie user IDs retain their assigned home even if new shard creation is switched off. */
export function directoryForUser(env: Env, userId: string) {
  return directoryByName(env, directoryNameForUser(userId));
}

/** Administrative operations must still see old shards after a configuration rollback. */
export function* allDirectories(
  env: Env,
): Generator<ReturnType<typeof directory>> {
  yield directory(env);
  for (let shard = 0; shard < 16; shard++)
    yield directoryByName(env, `directory-${shard}`);
}

/** A user's vault, addressed by the ID from their verified session cookie. */
export function vault(env: Env, vaultId: string) {
  return env.VAULT.get(env.VAULT.idFromString(vaultId));
}
